276	    private static boolean isBlank(String value) {
277	        return value == null || value.isBlank();
278	    }
279	
280	    /**
281	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
282	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
283	     */
284	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
285	        "NSW", new int[] {2000, 2099},
286	        "VIC", new int[] {3000, 3099},
287	        "QLD", new int[] {4000, 4099});
288	
289	    /**
290	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
291	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
292	     * present, the value has already passed the 4-digit format check (Bean Validation on the
293	     * request body); this enforces that it falls within the inclusive range for the city's region
294	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
295	     *
296	     * @param postcode the supplied postcode (may be {@code null})
297	     * @param region the owner's locality/region derived from its city
298	     * @throws InvalidPostcodeException if the postcode is out of range for the region
299	     */
300	    private static void validatePostcode(String postcode, String region) {
301	        if (isBlank(postcode)) {
302	            return;
303	        }
304	        int[] range = REGION_POSTCODES.get(region);
305	        if (range == null) {
306	            return;
307	        }
308	        int value;
309	        try {
310	            value = Integer.parseInt(postcode);
311	        }
312	        catch (NumberFormatException e) {
313	            throw new InvalidPostcodeException(postcode);
314	        }
315	        if (value < range[0] || value > range[1]) {
316	            throw new InvalidPostcodeException(postcode);
317	        }
318	    }
319	
320	    /**
321	     * Normalizes a street address into the canonical form stored on and returned for a newly
322	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
323	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
324	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
325	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
326	     * value is what gets persisted, echoed back, and used for every address comparison (household
327	     * duplicate detection and the shared household identifier).
328	     *
329	     * @param rawAddress the address value as supplied by the client
330	     * @return the normalized address (possibly empty, never {@code null})
331	     */
332	    private static String normalizeAddress(String rawAddress) {
333	        if (rawAddress == null) {
334	            return "";
335	        }
336	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
337	        if (collapsed.isEmpty()) {
338	            return "";
339	        }
340	        String[] tokens = collapsed.split(" ");
341	        StringBuilder sb = new StringBuilder(collapsed.length());
342	        for (int i = 0; i < tokens.length; i++) {
343	            String token = tokens[i];
344	            switch (token) {
345	                case "ST" -> token = "STREET";
346	                case "RD" -> token = "ROAD";
347	                case "AVE" -> token = "AVENUE";
348	                default -> { }
349	            }
350	            if (i > 0) {
351	                sb.append(' ');
352	            }
353	            sb.append(token);
354	        }
355	        return sb.toString();
356	    }
357	
358	    /**
359	     * Builds the customer code assigned to a newly created owner. The code is formatted
360	     * {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the upper-cased first three letters
361	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's
362	     * last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more
363	     * than the number of owners already in that city (e.g. {@code LON-SMI-0007}).
364	     *
365	     * @param city the city of the owner being created
366	     * @param lastName the last name of the owner being created
367	     * @return the customer code to assign
368	     */
369	    private String nextCustomerCode(String city, String lastName) {
370	        String city3 = letterPrefix3(city);
371	        String last3 = letterPrefix3(lastName);
372	        String normalizedCity = normalizeIdentity(city);
373	        long sequence = this.clinicService.findAllOwners().stream()
374	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
375	            .count() + 1L;
376	        return String.format("%s-%s-%04d", city3, last3, sequence);
377	    }
378	
379	    /**
380	     * Returns the upper-cased first three letters of the given value, skipping any non-letter
381	     * characters. Values with fewer than three letters yield a shorter prefix.
382	     *
383	     * @param value the source text
384	     * @return the upper-cased letter prefix (at most three characters, never {@code null})
385	     */
386	    private static String letterPrefix3(String value) {
387	        StringBuilder prefix = new StringBuilder(3);
388	        if (value != null) {
389	            for (int i = 0; i < value.length() && prefix.length() < 3; i++) {
390	                char c = value.charAt(i);
391	                if (Character.isLetter(c)) {
392	                    prefix.append(Character.toUpperCase(c));
393	                }
394	            }
395	        }
396	        return prefix.toString();
397	    }
398	
399	    /**
400	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
401	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
402	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
403	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
404	     * the national number must match the country code: {@code +61} requires 9 national digits and
405	     * {@code +1} requires 10.
406	     *
407	     * @param rawTelephone the telephone value as supplied by the client
408	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
409	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
410	     */
411	    private static String normalizeTelephone(String rawTelephone) {
412	        if (rawTelephone == null) {
413	            throw new InvalidTelephoneException(rawTelephone);
414	        }
415	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
416	        String e164;
417	        if (cleaned.startsWith("+")) {
418	            String digits = cleaned.substring(1);
419	            if (!digits.matches("[0-9]+")) {
420	                throw new InvalidTelephoneException(rawTelephone);
421	            }
422	            e164 = "+" + digits;
423	        } else {
424	            if (!cleaned.matches("[0-9]+")) {
425	                throw new InvalidTelephoneException(rawTelephone);
426	            }
427	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
428	            e164 = "+61" + national;
429	        }
430	        int digitCount = e164.length() - 1;
431	        if (digitCount < 8 || digitCount > 15) {
432	            throw new InvalidTelephoneException(rawTelephone);
433	        }
434	        if (e164.startsWith("+61")) {
435	            if (e164.length() - "+61".length() != 9) {
436	                throw new InvalidTelephoneException(rawTelephone);
437	            }
438	        }
439	        else if (e164.startsWith("+1")) {
440	            if (e164.length() - "+1".length() != 10) {
441	                throw new InvalidTelephoneException(rawTelephone);
442	            }
443	        }
444	        return e164;
445	    }
446	
447	    /**
448	     * Determines whether any existing owner already carries the given identity key. The identity key
449	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
450	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
451	     * are equal.
452	     *
453	     * @param identityKey the identity key of the owner being created
454	     * @return {@code true} if another owner already has the same identity key
455	     */
456	    private boolean isIdentityKeyInUse(String identityKey) {
457	        return this.clinicService.findAllOwners().stream()
458	            .map(Owner::getIdentityKey)
459	            .anyMatch(identityKey::equals);
460	    }
461	
462	    /**
463	     * Counts how many existing owners already share the given first name and last name with the
464	     * owner being created. Both names are compared case-insensitively (after trimming and
465	     * collapsing runs of whitespace). The count reflects the state before the new owner is
466	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
467	     *
468	     * @param firstName the first name of the owner being created
469	     * @param lastName the last name of the owner being created
470	     * @return the number of existing owners sharing the same first and last name
471	     */
472	    private int namesakeCount(String firstName, String lastName) {
473	        String normalizedFirstName = normalizeIdentity(firstName);
474	        String normalizedLastName = normalizeIdentity(lastName);
475	        return (int) this.clinicService.findAllOwners().stream()
476	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
477	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
478	            .count();
479	    }
480	
481	    /**
482	     * Counts how many members the owner being created belongs to in its household, including
483	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
484	     * the new owner is not yet persisted, so its own membership is added to the existing count.
485	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
486	     * household of one.
487	     *
488	     * @param householdId the shared household identifier assigned to the owner being created, or
489	     *                    {@code null} if the owner does not share a household
490	     * @return the number of household members after this create (at least 1)
491	     */
492	    private int householdSizeAfterCreate(String householdId) {
493	        if (householdId == null) {
494	            return 1;
495	        }
496	        long existing = this.clinicService.findAllOwners().stream()
497	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
498	            .count();
499	        return (int) existing + 1;
500	    }
501	
502	    /**
503	     * The maximum number of owners permitted in a single city. Once a city already contains this
504	     * many owners it is considered full and no further owners may be created there.
505	     */
506	    private static final int CITY_CAPACITY = 50;
507	
508	    /**
509	     * Determines whether the given city has already reached its capacity, i.e. already contains
510	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
511	     * collapsing runs of whitespace to a single space and trimming.
512	     *
513	     * @param city the city of the owner being created
514	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
515	     */
516	    private boolean isCityAtCapacity(String city) {
517	        String normalizedCity = normalizeIdentity(city);
518	        long count = this.clinicService.findAllOwners().stream()
519	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
520	            .count();
521	        return count >= CITY_CAPACITY;
522	    }
523	
524	    /**
525	     * The maximum number of owners that may be created on any single day. Once this many owners
526	     * already carry a {@code registrationDate} of the current day, no further owners may be created
527	     * that day.
528	     */
529	    private static final int DAILY_REGISTRATION_LIMIT = 100;
530	
531	    /**
532	     * Determines whether the daily registration limit has already been reached, i.e. whether
533	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
534	     * their {@code registrationDate}.
535	     *
536	     * @param date the current day
537	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
538	     *         registered on the given date
539	     */
540	    /**
541	     * Rolls a registration date forward onto a business day. A date that already falls on a
542	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
543	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
544	     * everything derived from it (the membership number's year segment, the daily create-limit).
545	     *
546	     * @param date the effective registration date (supplied by the client or defaulted to the
547	     *             server's current date)
548	     * @return the same date if it is a weekday, otherwise the following Monday
549	     */
550	    private static LocalDate toBusinessDay(LocalDate date) {
551	        DayOfWeek dayOfWeek = date.getDayOfWeek();
552	        if (dayOfWeek == DayOfWeek.SATURDAY) {
553	            return date.plusDays(2);
554	        }
555	        if (dayOfWeek == DayOfWeek.SUNDAY) {
556	            return date.plusDays(1);
557	        }
558	        return date;
559	    }
560	
561	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
562	        long count = this.clinicService.findAllOwners().stream()
563	            .filter(existing -> date.equals(existing.getRegistrationDate()))
564	            .count();
565	        return count >= DAILY_REGISTRATION_LIMIT;
566	    }
567	
568	    /**
569	     * The number of owners that may be created on a single day before the bulk-signup warning is
570	     * raised. Once <em>more than</em> this many owners already carry the current business day as
571	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
572	     */
573	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
574	
575	    /**
576	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
577	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
578	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
579	     *
580	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
581	     *         registered on today's business day
582	     */
583	    private boolean isBulkSignupWarning() {
584	        LocalDate today = toBusinessDay(LocalDate.now());
585	        long count = this.clinicService.findAllOwners().stream()
586	            .filter(existing -> today.equals(existing.getRegistrationDate()))
587	            .count();
588	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
589	    }
590	
591	    /**
592	     * Back-fills the given household identifier onto every existing member of the household (those
593	     * sharing the same last name and address) that does not yet carry it, so all household members
594	     * share the stable identifier regardless of creation order. The identifier itself is derived
595	     * deterministically by {@link #householdIdFor(String, String)}.
596	     *
597	     * @param lastName the last name of the owner being created
598	     * @param address the address of the owner being created
599	     * @param householdId the stable household identifier assigned to the owner being created
600	     */
601	    private void backfillHousehold(String lastName, String address, String householdId) {
602	        String normalizedLastName = normalizeIdentity(lastName);
603	        String normalizedAddress = normalizeIdentity(address);
604	        for (Owner existing : this.clinicService.findAllOwners()) {
605	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
606	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
607	                && !householdId.equals(existing.getHouseholdId())) {
608	                existing.setHouseholdId(householdId);
609	                this.clinicService.saveOwner(existing);
610	            }
611	        }
612	    }
613	
614	    /**
615	     * Derives the stable household identifier for a given last name and address. The value is the
616	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
617	     * address, so it is stable across calls and identical for every member of the household.
618	     *
619	     * @param lastName the last name of the household
620	     * @param address the address of the household
621	     * @return the stable household identifier
622	     */
623	    private static String householdIdFor(String lastName, String address) {
624	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
625	        try {
626	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
627	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
628	            StringBuilder sb = new StringBuilder(digest.length * 2);
629	            for (byte b : digest) {
630	                sb.append(String.format("%02x", b));
631	            }
632	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
633	        }
634	        catch (java.security.NoSuchAlgorithmException e) {
635	            throw new IllegalStateException("SHA-256 not available", e);
636	        }
637	    }
638	
639	    /**
640	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
641	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
642	     * single space, and the result is lower-cased.
643	     *
644	     * @param value the raw field value
645	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
646	     */
647	    private static String normalizeIdentity(String value) {
648	        if (value == null) {
649	            return "";
650	        }
651	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
652	    }
653	}
